// constat:template id=constat-journeys-script version=52 sha256=c4319585f68adb0658f283f08de391d115c46a650435e25bd1a450d8461b2967
// Generated by DoneMark. Walks every journey in journeys/ on the running copy of this branch,
// photographs each step, and writes one report DoneMark reads: .constat/journeys/constat-journeys.json.
// A journey is code in this repository, written as part of a feature; DoneMark never runs one.
import { mkdirSync, readdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const OUT = '.constat/journeys';
const STEP_MS = 30000;
const address = (process.argv[2] || '').trim().replace(/\/+$/, '');
if (!/^https?:\/\//.test(address)) {
  console.log('::error::There is no address to walk the journeys on.');
  process.exit(1);
}
const where = process.env.CONSTAT_PLAYWRIGHT;
if (!where) {
  console.log('::error::CONSTAT_PLAYWRIGHT does not say where the browser library was installed.');
  process.exit(1);
}
const { chromium } = await import(pathToFileURL(join(where, 'index.mjs')).href);
mkdirSync(OUT, { recursive: true });

/** The first line of what went wrong, without a terminal's colours: what the page shows. */
function firstLine(err) {
  const text = String(err && err.message ? err.message : err).replace(/\u001b\[[0-9;]*m/g, '');
  return (text.split('\n').find((l) => l.trim() !== '') || 'it failed').trim().slice(0, 300);
}
function slug(text) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'journey';
}
function journeyFiles(dir) {
  let names = [];
  try { names = readdirSync(dir).sort(); } catch { return []; }
  return names.flatMap((name) => {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) return journeyFiles(path);
    return name.endsWith('.journey.mjs') ? [path] : [];
  });
}

let copyAnswered = null;
try { copyAnswered = JSON.parse(readFileSync('.constat/preview/version.json', 'utf8')).commit || null; } catch { copyAnswered = null; }
const bypass = process.env.BYPASS || '';
const report = {
  schema: 'constat.journeys/v1',
  commit: process.env.GITHUB_SHA || null,
  url: address,
  copyAnswered,
  ranAt: new Date().toISOString().replace(/\.\d+Z$/, 'Z'),
  journeys: [],
};

const browser = await chromium.launch();
const files = journeyFiles('journeys');
for (let j = 0; j < files.length; j++) {
  const file = files[j].split('\\').join('/');
  const one = { file, name: file.replace(/^.*\//, '').replace(/\.journey\.mjs$/, ''), steps: [], walkedToTheEnd: false, stopped: null, seconds: 0, video: null };
  report.journeys.push(one);
  let journey = null;
  try { journey = (await import(pathToFileURL(resolve(file)).href)).default; }
  catch (err) { one.stopped = { step: 0, why: 'the journey could not be read: ' + firstLine(err) }; continue; }
  if (!journey || !Array.isArray(journey.steps) || journey.steps.length === 0) {
    one.stopped = { step: 0, why: 'the journey names no steps: it exports default { name, steps: [...] }' };
    continue;
  }
  one.name = String(journey.name || one.name).slice(0, 200);
  const stem = (j + 1) + '-' + slug(one.name);
  const context = await browser.newContext({
    viewport: { width: 1280, height: 800 },
    recordVideo: { dir: join(OUT, 'video-' + stem), size: { width: 1280, height: 800 } },
    extraHTTPHeaders: bypass ? { 'x-vercel-protection-bypass': bypass, 'x-vercel-set-bypass-cookie': 'true' } : {},
  });
  const page = await context.newPage();
  page.setDefaultTimeout(STEP_MS);
  const hands = {
    page,
    url: (path) => address + (path ? (path.startsWith('/') ? path : '/' + path) : '/'),
    see: async (text) => {
      try { await page.getByText(String(text)).first().waitFor({ state: 'visible' }); }
      catch { throw new Error('"' + String(text).slice(0, 120) + '" was not on the screen'); }
    },
  };
  const started = Date.now();
  for (let i = 0; i < journey.steps.length; i++) {
    const step = journey.steps[i] || {};
    const n = i + 1;
    const said = { n, title: String(step.title || 'Step ' + n).slice(0, 200), sees: Array.isArray(step.sees) ? step.sees.map((s) => String(s).slice(0, 500)) : [], picture: stem + '-' + n + '.png', ok: false };
    one.steps.push(said);
    try {
      if (typeof step.run !== 'function') throw new Error('this step has no run');
      await step.run(hands);
      said.ok = true;
    } catch (err) {
      one.stopped = { step: n, why: firstLine(err) };
    }
    try { await page.screenshot({ path: join(OUT, said.picture) }); } catch { said.picture = null; }
    if (!said.ok) break;
  }
  one.walkedToTheEnd = one.stopped === null;
  one.seconds = Math.round((Date.now() - started) / 1000);
  const video = page.video();
  await context.close();
  if (video) {
    try { renameSync(await video.path(), join(OUT, stem + '.webm')); one.video = stem + '.webm'; } catch { one.video = null; }
  }
  rmSync(join(OUT, 'video-' + stem), { recursive: true, force: true });
  console.log(one.walkedToTheEnd
    ? 'Walked to the end: ' + one.name + ' (' + one.steps.length + ' steps, ' + one.seconds + ' s)'
    : 'Stopped at step ' + one.stopped.step + ': ' + one.name + ': ' + one.stopped.why);
}
await browser.close();
writeFileSync(join(OUT, 'constat-journeys.json'), JSON.stringify(report, null, 2) + '\n');
console.log('Walked ' + report.journeys.length + ' journey(s) on ' + address + '.');
